        action = {
            'type': 'ir.actions.client',
            'tag': 'display_notification',
            'params': {
                'title': 'القرار موجود',
                'message': 'يوجد قرار تعيين مولد بالفعل لهذا المتقدم. استخدم تحديث القرار أو فتح القرار.',
                'type': 'warning',
                'sticky': False,
                'next': applicant_reload_action(applicant),
