                'params': {
                    'title': 'قالب القرار غير موجود',
                    'message': 'لم يتم العثور على قالب RECRUITMENT_HIRING_DECISION النشط في GRC.',
                    'type': 'danger',
                    'sticky': True,
                },
            }
        else:
            instance = create_instance_from_template(template, applicant)
            write_applicant_variables(instance, applicant)
