                'params': {
                    'title': 'تم إنشاء القرار',
                    'message': 'تم إنشاء قرار التعيين وربطه بسجل المتقدم.',
                    'type': 'success',
                    'sticky': False,
                    'next': applicant_reload_action(applicant),
                },
            }

